-- Explicações por artigo — Lei de Atribuições da Polícia Federal em Crimes Interestaduais (Lei nº 10.446, de 2002). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na forma do inciso I do §1º do art. 144 da Constituição, quando houver repercussão interestadual ou internacional que exija repressão uniforme, poderá a Polícia Federal, sem prejuízo da responsabilidade dos demais órgãos de segurança pública, em especial das Polícias Militares e Civis dos Estados, investigar, entre outras, infrações como: sequestro, cárcere privado e extorsão mediante sequestro, se o agente foi impelido por motivação política ou em razão da função pública exercida pela vítima; formação de cartel; violações a direitos humanos que o Brasil se comprometeu a reprimir por tratados; furto, roubo ou receptação de cargas, inclusive produtos controlados como pólvoras e explosivos, em operação interestadual ou internacional, com indícios de quadrilha em mais de um Estado; falsificação, adulteração e venda de produtos terapêuticos ou medicinais; furto, roubo ou dano contra instituições financeiras, com indícios de associação criminosa em mais de um Estado; crimes na internet que difundam conteúdo misógino; e furto, roubo ou dano contra empresas de transporte de valores. Atendidos os pressupostos, a PF apurará outros casos autorizados ou determinados pelo Ministro da Justiça.', '["Exige repercussão interestadual ou internacional e necessidade de repressão uniforme.","Atribuição concorrente: não exclui as polícias estaduais.","Rol de infrações (incisos I a VIII).","Outros casos podem ser autorizados ou determinados pelo Ministro da Justiça."]'::jsonb, '["ATUALIZAÇÃO: incisos acrescidos por leis posteriores (por exemplo, o inciso VII sobre conteúdo misógino na internet e o inciso VIII sobre transporte de valores).","A atribuição é CONCORRENTE com as polícias estaduais."]'::jsonb, 'Roubo de cargas por quadrilha que atua em mais de um Estado pode ser investigado pela Polícia Federal.', '["Assertiva que afasta a atribuição das Polícias Civis nesses casos erra: a PF atua sem prejuízo dos demais órgãos."]'::jsonb, '[{"termo":"Repressão uniforme","significado":"Atuação coordenada em mais de um Estado ou país."}]'::jsonb, '["Constituição, art. 144, §1º, I"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pf-interestadual' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei entra em vigor na data de sua publicação, produzindo efeitos desde então.', '["Vigência imediata."]'::jsonb, '["Dispositivo final."]'::jsonb, 'A Lei passou a valer na data da publicação.', '["Assertiva que prevê vacatio legis erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pf-interestadual' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();
